void ALUUnit::update() {
    for (auto &&r_id : rs) {
        RS* r = e->get_rs(r_id);
        if (r->Busy) {
            if (r->Qj == NONE && r->Qk == NONE) {
                Immediate result = get_result(r->Op, r->Vj, r->Vk);
                e->put_result(r_id, result);
                r->Busy = false;
            }
        }
    }
}

Immediate ALUUnit::get_result(Immediate op, Immediate op1, Immediate op2) {
    if (op == ADD) return op1 + op2;
    if (op == SUB) return op1 - op2;
    if (op == SLT) { if ((SImmediate) op1 < (SImmediate) op2) return 1; else return 0; }
    if (op == SLTU) { if (op1 < op2) return 1; else return 0; }
    if (op == XOR) return op1 ^ op2;
    if (op == SRL) return op1 >> (op2 & (unsigned) 0x1f);
    if (op == SLL) return op1 << (op2 & (unsigned) 0x1f);
    if (op == SRA) return (SImmediate) op1 >> (op2 & (unsigned) 0x1f);
    if (op == OR) return op1 | op2;
    if (op == AND) return op1 & op2;
    assert(false);
    return 0;
}

std::string ALUUnit::resolve(ALUUnit::OP op) {
    switch(op) {
        case ADD: return "ADD";
        case SUB: return "SUB";
        case SLT: return "SLT";
        case SLTU: return "SLTU";
        case XOR: return "XOR";
        case SRL: return "SRL";
        case SLL: return "SLL";
        case SRA: return "SRA";
        case OR: return "OR";
        case AND: return "AND";
        case NONE_OP: return "NONE";
    }
    return "UNKNOWN";
}

BranchPrediction::BranchPrediction() {
    memset(two_bits, 0, sizeof(two_bits));
    memset(mux, 0, sizeof(mux));
}

bool BranchPrediction::take(unsigned addr) {
    return two_bits[addr + (mux[addr] & 0x3)] >= 2;
}

void BranchPrediction::report(unsigned addr, bool taken) {
    unsigned branch_addr = addr + (mux[addr] & 0x3);
    if (taken) {
        if (two_bits[branch_addr] < 3) two_bits[branch_addr]++;
    } else {
        if (two_bits[branch_addr] > 0) two_bits[branch_addr]--;
    }
    mux[addr] = mux[addr] << 1 | (taken ? 1 : 0);
}

void CommitUnit::update() {
    auto &rob_front = e->rob_front;
    auto &rob_entry = e->rob[rob_front];
    if (rob_entry.Ready) {
        InstructionBase inst = rob_entry.Inst;
        switch (inst.opcode) {
            case 0:
                break;
            case 0b0100011: // STORE
                resolve_store(rob_entry);
                break;
            case 0b1100011: // BRANCH
                resolve_branch(rob_entry);
                break;
            case 0b1100111: // JALR
                resolve_jalr(rob_entry);
                break;
            case 0b0110111: // LUI
            case 0b0010111: // AUIPC
            case 0b0010011: // OP-IMM
            case 0b0110011: // OP
            case 0b1101111: // JAL
            case 0b0000011: // LOAD
                resolve_op(rob_entry, rob_front);
                break;
            default:
                assert(false);
        }
        rob_front = OoOExecute::next_rob_entry(rob_front);
    }
}

void CommitUnit::resolve_branch(ROB &rob_entry) {
    InstructionBase inst = rob_entry.Inst;
    auto pc = rob_entry.Dest;
    auto next_pc = get_next_pc(inst, rob_entry, pc);

    bool taken = next_pc != pc + 4;

    e->session->branch->report(pc, taken);
    e->stat.total_branch++;

    if (next_pc != rob_entry.Tag) {
        e->flush_rob();
        e->session->i->notify_jump(next_pc);
    } else e->stat.correct_branch++;

    flush_rob_entry(rob_entry);
}

void CommitUnit::resolve_op(ROB &rob_entry, unsigned rob_id) {
    e->session->rf.write(rob_entry.Dest, rob_entry.Value);

    if (e->Reorder[rob_entry.Dest].current() == rob_id) {
        e->Busy[rob_entry.Dest] = false;
    }

    flush_rob_entry(rob_entry);
}

Immediate CommitUnit::get_next_pc(InstructionBase &inst, ROB &rob_entry, Immediate pc) {
    auto branch_target = pc + inst.imm;
    auto next_inst = pc + 4;
    switch (inst.funct3) {
        case 0b000: // BEQ
            if (rob_entry.Value == 0) return branch_target;
            else return next_inst;
        case 0b001: // BNE
            if (rob_entry.Value != 0) return branch_target;
            else return next_inst;
        case 0b100: // BLT
            if (rob_entry.Value == 1) return branch_target;
            else return next_inst;
        case 0b101: // BGE
            if (rob_entry.Value == 0) return branch_target;
            else return next_inst;
        case 0b110: // BLTU
            if (rob_entry.Value == 1) return branch_target;
            else return next_inst;
        case 0b111: // BGEU
            if (rob_entry.Value == 0) return branch_target;
            else return next_inst;
    }
    assert(false);
    return 0;
}

void CommitUnit::resolve_store(ROB &rob_entry) {
    InstructionBase inst = rob_entry.Inst;
    switch (inst.funct3) {
        case 0b000: // SB
            e->session->memory[rob_entry.Dest] = rob_entry.Value;
            break;
        case 0b001: // SH
            e->session->memory.write_ushort(rob_entry.Dest, rob_entry.Value);
            break;
        case 0b010: // SW
            e->session->memory.write_word(rob_entry.Dest, rob_entry.Value);
            break;
        default:
            assert(false);
    }

    flush_rob_entry(rob_entry);
}

void CommitUnit::resolve_jalr(ROB &rob_entry) {
    e->flush_rob();
    e->session->i->notify_jump(rob_entry.Value);
}

void CommitUnit::flush_rob_entry(ROB &rob_entry) {
    rob_entry.Ready = false;
    rob_entry.Inst = InstructionBase::nop();
}

void LoadStoreUnit::update() {
    for (auto &&r_id : rs_load) {
        RS *r = e->get_rs(r_id);
        if (r->Busy) {
            auto &load_cnt = get_load_cnt_register(r_id);
            // here load takes 3 cycles
            if (load_cnt == 0) {
                if (r->Qj == NONE) {
                    r->A = r->Vj + r->A;
                    load_cnt = 1;
                }
            } else if (load_cnt == 1) {
                if (no_store_in_rob(r->A, r->Dest)) {
                    load_value(r, get_load_buffer(r_id));
                    load_cnt = 2;
                } else {
                    ++e->stat.hazard_load;
                }
            } else if (load_cnt == 2) {
                commit_value(r_id, get_load_buffer(r_id));
                r->Busy = false;
                load_cnt = 0;
            } else
                assert(false);
        }
    }
    for (auto &&r_id : rs_store) {
        RS *r = e->get_rs(r_id);
        if (r->Busy) {
            auto &store_cnt = get_store_cnt_register(r_id);
            if (store_cnt == 0) {
                if (r->Qj == NONE) {
                    e->rob[r->Dest].Dest = r->Vj + r->A;
                    store_cnt = 1;
                }
            } else if (store_cnt == 1) {
                if (r->Qk == NONE) {
                    e->put_result(r_id, r->Vk);
                    r->Busy = false;
                    store_cnt = 0;
                }
            } else
                assert(false);
        }
    }
}

LoadStoreUnit::LoadStoreUnit(OoOExecute *e)
        : e(e), rs_load({LOAD1, LOAD2, LOAD3}), rs_store({STORE1, STORE2, STORE3}) {
    reset();
}

void LoadStoreUnit::load_value(RS *rs, Register<Immediate> &load_buffer) {
    switch (rs->Op) {
        case 0b000: // LB
            load_buffer = (char) e->session->memory[rs->A];
            break;
        case 0b001: // LH
            load_buffer = (short) e->session->memory.read_ushort(rs->A);
            break;
        case 0b010: // LW
            load_buffer = e->session->memory.read_word(rs->A);
            break;
        case 0b100: // LBU
            load_buffer = e->session->memory[rs->A];
            break;
        case 0b101: // LHU
            load_buffer = e->session->memory.read_ushort(rs->A);
            break;
        default:
            assert(false);
    }
}

void LoadStoreUnit::commit_value(RSID r_id, Immediate val) {
    e->put_result(r_id, val);
}

void LoadStoreUnit::tick() {
    for (int i = 0; i < LOAD_BUFFER_SIZE; i++) load_cnt[i].tick();
    for (int i = 0; i < LOAD_BUFFER_SIZE; i++) load_buffer[i].tick();
    for (int i = 0; i < STORE_BUFFER_SIZE; i++) store_cnt[i].tick();
}

bool LoadStoreUnit::no_store_in_rob(unsigned addr, unsigned current_rob) {
    if (current_rob == 0) return true;
    for (unsigned i = e->rob_front; i != current_rob; i = OoOExecute::next_rob_entry(i)) {
        InstructionBase inst = e->rob[i].Inst;
        if (inst.opcode == 0b0100011) { // STORE
            if (e->rob[i].Dest == addr) return false;
        }
    }
    return true;
}

void LoadStoreUnit::reset() {
    for (int i = 0; i < LOAD_BUFFER_SIZE; i++) load_cnt[i] = 0;
    for (int i = 0; i < STORE_BUFFER_SIZE; i++) store_cnt[i] = 0;
}

Register<int> &LoadStoreUnit::get_store_cnt_register(RSID r_id) {
    switch (r_id) {
        case STORE1:
            return store_cnt[0];
        case STORE2:
            return store_cnt[1];
        case STORE3:
            return store_cnt[2];
        default:
            assert(false);
    }
}

Register<int> &LoadStoreUnit::get_load_cnt_register(RSID r_id) {
    switch (r_id) {
        case LOAD1:
            return load_cnt[0];
        case LOAD2:
            return load_cnt[1];
        case LOAD3:
            return load_cnt[2];
        default:
            assert(false);
    }
}

Register<Immediate> &LoadStoreUnit::get_load_buffer(RSID r_id) {
    switch (r_id) {
        case LOAD1:
            return load_buffer[0];
        case LOAD2:
            return load_buffer[1];
        case LOAD3:
            return load_buffer[2];
        default:
            assert(false);
    }
}

void Issue::update() {
    // Note that pc is register. No matter how
    // many times update is executed, pc always
    // stays the same.

    auto _inst = session->memory.read_word(pc);
    auto inst = parse_inst(_inst & 0x7f, _inst);

    pc = issue(inst);
}

void Issue::tick() {
    if (instruction_stalled()) stat.stall_cycle++;
    if (__jump_flag) {
        __jump_flag = false;
        pc = __jump_dest;
    }
    pc.tick();
    issue_cnt.tick();
}

ALUUnit::OP get_op_ri(InstructionBase inst) {
    switch (inst.funct3) {
        case 0b000:
            return ALUUnit::OP::ADD;
        case 0b010:
            return ALUUnit::OP::SLT;
        case 0b011:
            return ALUUnit::OP::SLTU;
        case 0b100:
            return ALUUnit::OP::XOR;
        case 0b110:
            return ALUUnit::OP::OR;
        case 0b111:
            return ALUUnit::OP::AND;
        case 0b001:
            return ALUUnit::OP::SLL;
        case 0b101:
            if (inst.imm & (1 << 9))
                return ALUUnit::OP::SRA;
            else
                return ALUUnit::OP::SRL;
    }
    assert(false);
    return ALUUnit::OP::NONE_OP;
}

ALUUnit::OP get_op_rr(InstructionBase inst) {
    switch (inst.funct3) {
        case 0b000:
            if (inst.funct7 == 0b0000000) return ALUUnit::OP::ADD;
            if (inst.funct7 == 0b0100000) return ALUUnit::OP::SUB;
        case 0b001:
            return ALUUnit::OP::SLL;
        case 0b010:
            return ALUUnit::OP::SLT;
        case 0b011:
            return ALUUnit::OP::SLTU;
        case 0b100:
            return ALUUnit::OP::XOR;
        case 0b101:
            if (inst.funct7 == 0b0000000)
                return ALUUnit::OP::SRL;
            if (inst.funct7 == 0b0100000)
                return ALUUnit::OP::SRA;
        case 0b110: // OR
            return ALUUnit::OP::OR;
        case 0b111: // AND
            return ALUUnit::OP::AND;
    }
    assert(false);
    return ALUUnit::OP::NONE_OP;
}

ALUUnit::OP get_op_branch(InstructionBase inst) {
    switch (inst.funct3) {
        case 0b000: // BEQ
        case 0b001: // BNE
            return ALUUnit::OP::SUB;
        case 0b100: // BLT
        case 0b101: // BGE
            return ALUUnit::OP::SLT;
        case 0b110: // BLTU
        case 0b111: // BGEU
            return ALUUnit::OP::SLTU;
    }
    assert(false);
    return ALUUnit::OP::NONE_OP;
}

Immediate Issue::issue(const InstructionBase &inst) {
    _debug_dispatched_inst = inst;
    issue_cnt.prev = issue_cnt.next = pc;

    if (inst.t == InstructionBase::J) { // JAL
        return issue_jal(inst);
    } else if (inst.t == InstructionBase::B) { // Branch
        return issue_branch(inst);
    } else if (inst.opcode == 0b1100111) { // JALR
        return issue_jalr(inst);
    } else if (inst.opcode == 0b0000011) { // Load
        return issue_load(inst);
    } else if (inst.opcode == 0b0100011) { // Store
        return issue_store(inst);
    } else if (inst.opcode == 0b0010011) { // Immediate Op
        return issue_immediate_op(inst);
    } else if (inst.opcode == 0b0110011) { // Op
        return issue_op(inst);
    } else if (inst.opcode == 0b0110111) { // LUI
        return issue_lui(inst);
    } else if (inst.opcode == 0b0110111) { // AUIPC
        return issue_auipc(inst);
    }
    return pc;
}

Issue::Issue(Session *session) :
